package com.hbm.client.wiaj.actors;
import com.mojang.blaze3d.vertex.*;import com.mojang.math.Axis;import java.util.Random;import net.minecraft.util.Mth;
/** Literal BeamPronter SOLID geometry for the original tutorial FEL, including its depth writes. */
public final class JarBeams {
 static void beam(JarRenderContext render,double length,int color,int start,int segments,float size,int layers,float thickness,boolean spiral){beam(render.pose(),render.buffers(),length,color,start,segments,size,layers,thickness,spiral);}
 public static void beam(PoseStack pose,net.minecraft.client.renderer.MultiBufferSource buffers,double length,int color,int start,int segments,float size,int layers,float thickness,boolean spiral){pose.pushPose();pose.mulPose(Axis.YP.rotationDegrees(180));float yaw=(float)(Math.atan2(0D,-length)*180F/Math.PI);pose.mulPose(Axis.YP.rotationDegrees(yaw));pose.mulPose(Axis.XP.rotationDegrees(-90));var out=buffers.getBuffer(JarRenderTypes.BEAM);var random=new Random(start);double lastX=0,lastY=0,lastZ=0,step=length/segments;for(int i=0;i<=segments;i++){double x=size,z=0;for(int turn=0;turn<2;turn++){float angle=spiral?turn==0?(float)Math.PI*start/180F:(float)Math.PI*45F/180F*i:(float)Math.PI*2*random.nextFloat();double next=x*Mth.cos(angle)+z*Mth.sin(angle);z=z*Mth.cos(angle)-x*Mth.sin(angle);x=next;}double y=step*i;if(i>0)for(int layer=1;layer<=layers;layer++){float radius=thickness/layers*layer;quad(out,pose,color,lastX+radius,lastY,lastZ+radius,lastX+radius,lastY,lastZ-radius,x+radius,y,z-radius,x+radius,y,z+radius);quad(out,pose,color,lastX-radius,lastY,lastZ+radius,lastX-radius,lastY,lastZ-radius,x-radius,y,z-radius,x-radius,y,z+radius);quad(out,pose,color,lastX+radius,lastY,lastZ+radius,lastX-radius,lastY,lastZ+radius,x-radius,y,z+radius,x+radius,y,z+radius);quad(out,pose,color,lastX+radius,lastY,lastZ-radius,lastX-radius,lastY,lastZ-radius,x-radius,y,z-radius,x+radius,y,z-radius);}lastX=x;lastY=y;lastZ=z;}pose.popPose();}
 private static void quad(VertexConsumer out,PoseStack pose,int color,double... positions){for(int i=0;i<positions.length;i+=3)out.addVertex(pose.last(),(float)positions[i],(float)positions[i+1],(float)positions[i+2]).setColor(0xff000000|color);}
 private JarBeams(){}
}
